def parse_duration(s):
    if not s:
        return None
    try:
        s = s.lower()
        parts = s.split('h')
        if len(parts) == 1:
            parts = s.split('m')
            if len(parts) == 1:
                parts = s.split('s')
                if len(parts) == 1:
                    return None
                else:
                    return int(parts[0])
            else:
                minutes = int(parts[1].split('m')[0])
                return minutes * 60
        else:
            hours = int(parts[0])
            if len(parts[1]) == 0:
                return hours * 3600
            else:
                minutes = int(parts[1].split('m')[0])
                return hours * 3600 + minutes * 60
    except ValueError:
        return None
